import 'package:flutter/material.dart';import 'package:geolocator/geolocator.dart';import 'package:google_maps_flutter/google_maps_flutter.dart';import 'package:url_launcher/url_launcher.dart';import 'package:cloud_firestore/cloud_firestore.dart';import 'dart:async';import 'saved_screen.dart';import 'support_review_screen.dart';import '../services/ev_station_service.dart';import '../services/location_service.dart';import '../services/notification_service.dart';import '../utils/station_filter.dart';import '../widgets/station_card.dart';class HomeContentScreen extends StatefulWidget {  const HomeContentScreen({super.key});  @override  State<HomeContentScreen> createState() => _HomeContentScreenState();}class _HomeContentScreenState extends State<HomeContentScreen> {  // Both official and community stations share this visibility boundary.  // The only difference between the two lists is their source, not the  // radius they are visible within.  static const double stationRadiusKm = kStationRadiusKm;  GoogleMapController? mapController;  // Unfiltered sources. Filtering always runs from these so that a  // station dropping out of range can come back when the user moves  // closer, instead of being discarded permanently.  List<Map<String, dynamic>> _rawOfficialStations = [];  List<Map<String, dynamic>> _rawCommunityStations = [];  List<Map<String, dynamic>> officialStations = [];  List<Map<String, dynamic>> communityStations = [];  String nearestStationDistance = "--";  LatLng? userLocation;  bool isLoading = true;  bool isLocating = false;  bool usingFallbackLocation = false;  bool isFetchingStations = false;  String? errorMessage;  StreamSubscription<QuerySnapshot<Map<String, dynamic>>>?  _communityStationsSub;  final LatLng fallbackLocation = const LatLng(26.9124, 75.7873);  final ScrollController _scrollController = ScrollController();  final GlobalKey scrollViewKey = GlobalKey();  final GlobalKey nearbyStationsKey = GlobalKey();  final GlobalKey communityStationsKey = GlobalKey();  @override  void initState() {    super.initState();    listenToCommunityStations();    loadData();  }  @override  void didChangeDependencies() {    super.didChangeDependencies();    // Trigger the contextual reminders once, after the first frame.    WidgetsBinding.instance.addPostFrameCallback((_) {      NotificationService.instance.onHomeLoaded();    });  }  @override  void dispose() {    _communityStationsSub?.cancel();    _scrollController.dispose();    super.dispose();  }  // ================= LOCATION =================  /// Applies a new origin and recalculates every distance from it.  void _applyUserLocation(LatLng location) {    userLocation = location;    _recalculateDistances();  }  /// Filters one source against the shared radius.  List<Map<String, dynamic>> _prepareStations(    List<Map<String, dynamic>> stationList,  ) {    final origin = userLocation;    if (origin == null) return [];    return filterStationsWithinRadius(      stations: stationList,      originLat: origin.latitude,      originLng: origin.longitude,    );  }  /// Re-applies the shared radius to both lists from their unfiltered  /// sources. Called on every location change.  void _recalculateDistances() {    officialStations = _prepareStations(_rawOfficialStations);    communityStations = _prepareStations(_rawCommunityStations);    updateNearestStationDistance();  }  // ================= LOAD DATA =================  Future<void> loadData() async {    try {      final position = await LocationService.getCurrentPosition();      if (!mounted) return;      setState(() {        usingFallbackLocation = false;        errorMessage = null;      });      _applyUserLocation(        LatLng(position.latitude, position.longitude),      );      await _fetchEVStations(        position.latitude,        position.longitude,      );      _centerOnUser();      NotificationService.instance.onStationsLoaded(        nearestStationKm: _nearestStationKm(),      );    } on LocationFailure catch (failure) {      debugPrint('Location unavailable: ${failure.message}');      if (!mounted) return;      setState(() {        userLocation = fallbackLocation;        usingFallbackLocation = true;        errorMessage = null;      });      _recalculateDistances();    } catch (e, stackTrace) {      debugPrint('Load error: $e');      debugPrint('$stackTrace');      if (!mounted) return;      setState(() {        userLocation = fallbackLocation;        usingFallbackLocation = true;        errorMessage =            'Unable to load charging stations right now. '            'Please check your connection and try again.';      });    } finally {      if (mounted) {        setState(() {          isLoading = false;        });      }    }  }  /// Re-centres the map and recomputes distances on demand.  Future<void> refreshMyLocation() async {    if (isLocating) return;    setState(() {      isLocating = true;    });    try {      final position = await LocationService.getCurrentPosition();      if (!mounted) return;      // Capture before clearing: leaving the fallback state means the      // cached station data was fetched around the wrong centre and has      // to be refetched.      final wasUsingFallback = usingFallbackLocation;      setState(() {        usingFallbackLocation = false;      });      _applyUserLocation(        LatLng(position.latitude, position.longitude),      );      _centerOnUser();      if (wasUsingFallback) {        await _fetchEVStations(position.latitude, position.longitude);      }    } on LocationFailure catch (failure) {      if (!mounted) return;      _showLocationError(failure);    } catch (e) {      if (mounted) {        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(            content: Text("Could not get your location. Please try again."),          ),        );      }    } finally {      if (mounted) {        setState(() {          isLocating = false;        });      }    }  }  void _showLocationError(LocationFailure failure) {    ScaffoldMessenger.of(context).showSnackBar(      SnackBar(        content: Text(failure.message),        action: failure.canOpenSettings            ? SnackBarAction(                label: 'Settings',                textColor: const Color(0xFF00FFAA),                onPressed: () async {                  await Geolocator.openLocationSettings();                },              )            : null,      ),    );  }  void _centerOnUser() {    final location = userLocation;    if (mapController == null || location == null) return;    mapController!.animateCamera(      CameraUpdate.newCameraPosition(        CameraPosition(target: location, zoom: 14),      ),    );  }  // ================= FETCH EV STATIONS =================  Future<void> _fetchEVStations(double lat, double lng) async {    if (isFetchingStations) return;    setState(() {      isFetchingStations = true;    });    try {      final fetchedStations = await EVStationService.fetchEVStations(        lat: lat,        lng: lng,        radius: (stationRadiusKm * 1000).round(),      );      if (!mounted) return;      setState(() {        _rawOfficialStations = fetchedStations            .map(              (station) => {...station, "source": "google"},            )            .toList();        _recalculateDistances();      });    } catch (e) {      debugPrint('EV station error: $e');    } finally {      if (mounted) {        setState(() {          isFetchingStations = false;        });      }    }  }  // ================= COMMUNITY STATIONS =================  void listenToCommunityStations() {    _communityStationsSub = FirebaseFirestore.instance        .collection("charging_stations")        .where("isActive", isEqualTo: true)        .snapshots()        .listen(      (snapshot) {        final activeStations = <Map<String, dynamic>>[];        for (final doc in snapshot.docs) {          final data = doc.data();          final lat = data["latitude"];          final lng = data["longitude"];          if (data["isActive"] != true || lat is! num || lng is! num) {            continue;          }          final latValue = lat.toDouble();          final lngValue = lng.toDouble();          // Reject invalid coordinates so a bad document can never          // produce a wrong marker or a wrong distance.          if (latValue < -90 ||              latValue > 90 ||              lngValue < -180 ||              lngValue > 180) {            debugPrint(              'Skipping station ${doc.id} with invalid coordinates '              '$latValue,$lngValue',            );            continue;          }          activeStations.add({            ...data,            "id": doc.id,            "source": "community",            "name": data["stationName"] ?? "Community Charging Station",            "vicinity": data["location"] ?? "Address unavailable",            "geometry": {              "location": {"lat": latValue, "lng": lngValue},            },          });        }        if (!mounted) return;        setState(() {          _rawCommunityStations = activeStations;          _recalculateDistances();        });      },      onError: (e) {        debugPrint('Community stations stream error: $e');      },    );  }  // ================= OPEN MAP =================  Future<void> openMap(double lat, double lng) async {    final Uri url = Uri.parse(      "https://www.google.com/maps/dir/?api=1&destination=$lat,$lng",    );    try {      await launchUrl(url, mode: LaunchMode.externalApplication);    } catch (e) {      if (mounted) {        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(            content: Text("Could not open navigation."),          ),        );      }    }  }  double? _nearestStationKm() {    double? nearest;    for (final station in [      ...officialStations,      ...communityStations,    ]) {      final distance = station['distanceKm'];      if (distance is! double) continue;      if (nearest == null || distance < nearest) {        nearest = distance;      }    }    return nearest;  }  Future<void> openNearestStation() async {    Map<String, dynamic>? nearestStation;    double nearestDistance = double.infinity;    for (final station in [      ...officialStations,      ...communityStations,    ]) {      final distance = station['distanceKm'];      if (distance is! double) continue;      if (distance < nearestDistance) {        nearestDistance = distance;        nearestStation = station;      }    }    if (nearestStation == null) {      ScaffoldMessenger.of(context).showSnackBar(        const SnackBar(content: Text("No nearby charging station found.")),      );      return;    }    await openMap(      nearestStation['geometry']['location']['lat'],      nearestStation['geometry']['location']['lng'],    );  }  /// Scrolls a station section to the top of the viewport.  ///  /// The offset is computed manually rather than using ensureVisible so  /// the section header lands a few pixels below the top edge instead of  /// flush against it.  void scrollToSection(GlobalKey sectionKey) {    if (!_scrollController.hasClients) return;    final sectionContext = sectionKey.currentContext;    if (sectionContext == null) return;    final box = sectionContext.findRenderObject() as RenderBox?;    final viewport = scrollViewKey.currentContext?.findRenderObject();    if (box == null || viewport == null || !box.attached) return;    final position = _scrollController.position;    // Offset of the section relative to the top of the scroll viewport.    final delta = box.localToGlobal(      Offset.zero,      ancestor: viewport,    ).dy;    final target = (position.pixels + delta - 12).clamp(      position.minScrollExtent,      position.maxScrollExtent,    );    if ((target - position.pixels).abs() < 8) return;    _scrollController.animateTo(      target,      duration: const Duration(milliseconds: 500),      curve: Curves.easeOutCubic,    );  }  void scrollToCommunityStations() {    scrollToSection(communityStationsKey);  }  void scrollToOfficialStations() {    scrollToSection(nearbyStationsKey);  }  // ================= MARKERS =================  Set<Marker> getMarkers() {    final markers = <Marker>{};    for (final station in [      ...officialStations,      ...communityStations,    ]) {      final lat = station['geometry']?['location']?['lat'];      final lng = station['geometry']?['location']?['lng'];      if (lat is! num || lng is! num) continue;      final isCommunity = station['source'] == 'community';      markers.add(        Marker(          markerId: MarkerId(            '${station['source']}_'            '${station['place_id'] ?? station['id'] ?? station['name']}',          ),          position: LatLng(lat.toDouble(), lng.toDouble()),           icon: BitmapDescriptor.defaultMarkerWithHue(BitmapDescriptor.hueRed),          infoWindow: InfoWindow(            title: station['name'],            snippet: isCommunity                ? 'Community added'                : 'Google listed',          ),        ),      );    }    return markers;  }  void updateNearestStationDistance() {    final nearest = _nearestStationKm();    setState(() {      if (nearest == null) {        nearestStationDistance = "--";      } else if (nearest < 1) {        nearestStationDistance = "< 1 km";      } else {        nearestStationDistance = "${nearest.toStringAsFixed(1)} km";      }    });  }  // ================= QUICK ACTION CARD =================  Widget quickActionCard({    required IconData icon,    required String title,    required VoidCallback onTap,  }) {    return Expanded(      child: GestureDetector(        onTap: onTap,        child: Container(          padding: const EdgeInsets.all(18),          decoration: BoxDecoration(            color: const Color(0xFF111827),            borderRadius: BorderRadius.circular(22),          ),          child: Column(            children: [              Container(                padding: const EdgeInsets.all(14),                decoration: BoxDecoration(                  gradient: const LinearGradient(                    colors: [Color(0xFF00FFAA), Color(0xFF00E5FF)],                  ),                  borderRadius: BorderRadius.circular(18),                ),                child: Icon(icon, color: Colors.black, size: 28),              ),              const SizedBox(height: 12),              Text(                title,                textAlign: TextAlign.center,                style: const TextStyle(                  color: Colors.white,                  fontWeight: FontWeight.w600,                ),              ),            ],          ),        ),      ),    );  }  // ================= UI =================  @override  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: const Color(0xFF030712),      body: SafeArea(        child: isLoading            ? const Center(                child: CircularProgressIndicator(color: Color(0xFF00FFAA)),              )            : errorMessage != null            ? Center(                child: Padding(                  padding: const EdgeInsets.all(24),                  child: Column(                    mainAxisAlignment: MainAxisAlignment.center,                    children: [                      Text(                        errorMessage!,                        textAlign: TextAlign.center,                        style: const TextStyle(                          color: Colors.white,                          fontSize: 16,                        ),                      ),                      const SizedBox(height: 20),                      ElevatedButton(                        style: ElevatedButton.styleFrom(                          backgroundColor: const Color(0xFF00FFAA),                          foregroundColor: Colors.black,                        ),                        onPressed: () {                          setState(() {                            isLoading = true;                            errorMessage = null;                          });                          loadData();                        },                        child: const Text("Retry"),                      ),                    ],                  ),                ),              )            : SingleChildScrollView(                key: scrollViewKey,                controller: _scrollController,                child: Column(                  crossAxisAlignment: CrossAxisAlignment.start,                  children: [                    // ================= HEADER =================                    Padding(                      padding: const EdgeInsets.all(20),                      child: InkWell(                        onTap: () {                          Navigator.push(                            context,                            MaterialPageRoute(                              builder: (_) => const SupportReviewScreen(),                            ),                          );                        },                        borderRadius: BorderRadius.circular(20),                        child: Row(                          children: [                            Container(                              padding: const EdgeInsets.all(14),                              decoration: BoxDecoration(                                color: Colors.white10,                                borderRadius: BorderRadius.circular(20),                              ),                              child: const Icon(                                Icons.ev_station,                                color: Color(0xFF00FFAA),                                size: 30,                              ),                            ),                            const SizedBox(width: 16),                            const Column(                              crossAxisAlignment: CrossAxisAlignment.start,                              children: [                                Text(                                  "EVPLUG",                                  style: TextStyle(                                    color: Color(0xFF00FFAA),                                    fontSize: 28,                                    fontWeight: FontWeight.bold,                                  ),                                ),                                SizedBox(height: 4),                                Text(                                  "Find EV chargers instantly",                                  style: TextStyle(color: Colors.white54),                                ),                              ],                            ),                          ],                        ),                      ),                    ),                    // ================= MAP =================                    if (usingFallbackLocation)                      Container(                        margin: const EdgeInsets.symmetric(                          horizontal: 18,                          vertical: 8,                        ),                        padding: const EdgeInsets.all(12),                        decoration: BoxDecoration(                          color: const Color(0xFF111827),                          borderRadius: BorderRadius.circular(14),                        ),                        child: Row(                          children: [                            const Icon(                              Icons.location_off,                              color: Color(0xFF00FFAA),                              size: 18,                            ),                            const SizedBox(width: 10),                            const Expanded(                              child: Text(                                'Your location is unavailable. '                                'Distances below are measured from a default center, '                                'not from you. Tap "My Location" to try again.',                                style: TextStyle(                                  color: Colors.white70,                                  fontSize: 12,                                ),                              ),                            ),                          ],                        ),                      ),                    Container(                      height: 260,                      margin: const EdgeInsets.symmetric(horizontal: 18),                      child: ClipRRect(                        borderRadius: BorderRadius.circular(26),                        child: Stack(                          children: [                            GoogleMap(                              initialCameraPosition: CameraPosition(                                target: userLocation ?? fallbackLocation,                                zoom: 13,                              ),                              myLocationEnabled: true,                              myLocationButtonEnabled: false,                              markers: getMarkers(),                              onMapCreated: (controller) {                                mapController = controller;                              },                            ),                            // ================= MY LOCATION BUTTON =================                            Positioned(                              left: 14,                              bottom: 14,                              child: Semantics(                                button: true,                                label: 'My Location',                                child: Material(                                  color: const Color(0xFF111827),                                  shape: const CircleBorder(),                                  elevation: 4,                                  child: InkWell(                                    customBorder: const CircleBorder(),                                    onTap: isLocating ? null : refreshMyLocation,                                    child: Container(                                      width: 50,                                      height: 50,                                      alignment: Alignment.center,                                      child: isLocating                                          ? const SizedBox(                                              height: 22,                                              width: 22,                                              child:                                                  CircularProgressIndicator(                                                    color: Color(0xFF00FFAA),                                                    strokeWidth: 2.5,                                                  ),                                            )                                          : const Icon(                                              Icons.my_location,                                              color: Color(0xFF00FFAA),                                              size: 26,                                            ),                                    ),                                  ),                                ),                              ),                            ),                          ],                        ),                      ),                    ),                    const SizedBox(height: 28),                    // ================= QUICK ACTIONS =================                    const Padding(                      padding: EdgeInsets.symmetric(horizontal: 20),                      child: Text(                        "Quick Actions",                        style: TextStyle(                          color: Colors.white,                          fontSize: 22,                          fontWeight: FontWeight.bold,                        ),                      ),                    ),                    const SizedBox(height: 16),                    Padding(                      padding: const EdgeInsets.symmetric(horizontal: 18),                      child: Row(                        children: [                          quickActionCard(                            icon: Icons.map,                            title: "Find Station",                            onTap: openNearestStation,                          ),                          const SizedBox(width: 12),                          quickActionCard(                            icon: Icons.bookmark,                            title: "Saved",                            onTap: () {                              Navigator.push(                                context,                                MaterialPageRoute(                                  builder: (context) => const SavedScreen(),                                ),                              );                            },                          ),                        ],                      ),                    ),                    const SizedBox(height: 32),                    // ================= EV STATS =================                    const Padding(                      padding: EdgeInsets.symmetric(horizontal: 20),                      child: Text(                        "EV Statistics",                        style: TextStyle(                          color: Colors.white,                          fontSize: 22,                          fontWeight: FontWeight.bold,                        ),                      ),                    ),                    const SizedBox(height: 16),                    Padding(                      padding: const EdgeInsets.symmetric(horizontal: 18),                      child: Row(                        children: [                          Expanded(                            child: Container(                              padding: const EdgeInsets.all(20),                              decoration: BoxDecoration(                                color: const Color(0xFF111827),                                borderRadius: BorderRadius.circular(22),                              ),                              child: Column(                                children: [                                  Text(                                    "${officialStations.length + communityStations.length}",                                    style: const TextStyle(                                      color: Color(0xFF00FFAA),                                      fontSize: 30,                                      fontWeight: FontWeight.bold,                                    ),                                  ),                                  const SizedBox(height: 8),                                  const Text(                                    "Nearby Chargers",                                    textAlign: TextAlign.center,                                    style: TextStyle(color: Colors.white70),                                  ),                                ],                              ),                            ),                          ),                          const SizedBox(width: 16),                          Expanded(                            child: Container(                              padding: const EdgeInsets.all(20),                              decoration: BoxDecoration(                                color: const Color(0xFF111827),                                borderRadius: BorderRadius.circular(22),                              ),                              child: Column(                                children: [                                  Text(                                    nearestStationDistance,                                    style: const TextStyle(                                      color: Color(0xFF00FFAA),                                      fontSize: 30,                                      fontWeight: FontWeight.bold,                                    ),                                  ),                                  const SizedBox(height: 8),                                  const Text(                                    "Station",                                    textAlign: TextAlign.center,                                    style: TextStyle(color: Colors.white70),                                  ),                                ],                              ),                            ),                          ),                        ],                      ),                    ),                    const SizedBox(height: 28),                    // ============ DIRECT SECTION JUMP ============                    // Lets the user move straight to either station list                    // instead of scrolling past the other one.                    _SectionJumpBar(                      officialCount: officialStations.length,                      communityCount: communityStations.length,                      onJumpToOfficial: scrollToOfficialStations,                      onJumpToCommunity: scrollToCommunityStations,                    ),                    const SizedBox(height: 20),                    // ============ OFFICIAL / GOOGLE SECTION ============                    StationSectionHeader(                      sectionKey: nearbyStationsKey,                      icon: Icons.bolt,                      color: StationSourceStyle.official,                      title: "Google Listed Chargers",                      subtitle:                          'Stations from the official Google Places data source.',                      count: officialStations.length,                      onTap: scrollToOfficialStations,                    ),                    StationList(                      stations: officialStations,                      isCommunity: false,                      usingFallbackLocation: usingFallbackLocation,                      onNavigate: openMap,                      emptyMessage:                          "No Google-listed stations within "                          "${stationRadiusKm.toInt()} km.",                    ),                    // A full-width divider so the two sources can never                    // visually run together.                    const SizedBox(height: 20),                    Container(                      height: 1,                      margin: const EdgeInsets.symmetric(horizontal: 18),                      color: Colors.white.withValues(alpha: 0.08),                    ),                    const SizedBox(height: 28),                    // ============ COMMUNITY SECTION ============                    StationSectionHeader(                      sectionKey: communityStationsKey,                      icon: Icons.people,                      color: StationSourceStyle.community,                      title: "Community Stations",                      subtitle:                          'Added by EVPlug users, not by Google. '                          'Details here are community reported.',                      count: communityStations.length,                      onTap: scrollToCommunityStations,                    ),                    StationList(                      stations: communityStations,                      isCommunity: true,                      usingFallbackLocation: usingFallbackLocation,                      onNavigate: openMap,                      emptyMessage:                          "No community-added stations within "                          "${stationRadiusKm.toInt()} km yet.\n"                          "Tap + to add one.",                    ),                    const SizedBox(height: 40),                  ],                ),              ),      ),    );  }}/// Two buttons that jump straight to either station list.////// Each shows its live count so it is obvious whether a section has/// anything in it before jumping.class _SectionJumpBar extends StatelessWidget {  final int officialCount;  final int communityCount;  final VoidCallback onJumpToOfficial;  final VoidCallback onJumpToCommunity;  const _SectionJumpBar({    required this.officialCount,    required this.communityCount,    required this.onJumpToOfficial,    required this.onJumpToCommunity,  });  @override  Widget build(BuildContext context) {    return Padding(      padding: const EdgeInsets.symmetric(horizontal: 18),      child: Row(        children: [          Expanded(            child: _JumpButton(              icon: Icons.bolt,              label: "Google Listed",              count: officialCount,              color: StationSourceStyle.official,              onTap: onJumpToOfficial,            ),          ),          const SizedBox(width: 12),          Expanded(            child: _JumpButton(              icon: Icons.people,              label: "Community",              count: communityCount,              color: StationSourceStyle.community,              onTap: onJumpToCommunity,            ),          ),        ],      ),    );  }}class _JumpButton extends StatelessWidget {  final IconData icon;  final String label;  final int count;  final Color color;  final VoidCallback onTap;  const _JumpButton({    required this.icon,    required this.label,    required this.count,    required this.color,    required this.onTap,  });  @override  Widget build(BuildContext context) {    final isEmpty = count == 0;    return Material(      color: color.withValues(alpha: 0.10),      borderRadius: BorderRadius.circular(16),      child: InkWell(        borderRadius: BorderRadius.circular(16),        onTap: onTap,        child: Container(          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 12),          decoration: BoxDecoration(            borderRadius: BorderRadius.circular(16),            border: Border.all(              color: color.withValues(alpha: isEmpty ? 0.18 : 0.45),            ),          ),          child: Row(            children: [              Icon(                icon,                color: isEmpty ? color.withValues(alpha: 0.5) : color,                size: 22,              ),              const SizedBox(width: 10),              Expanded(                child: Text(                  label,                  maxLines: 1,                  overflow: TextOverflow.ellipsis,                  style: TextStyle(                    color: isEmpty ? Colors.white54 : Colors.white,                    fontSize: 13,                    fontWeight: FontWeight.w600,                  ),                ),              ),              const SizedBox(width: 6),              Container(                padding: const EdgeInsets.symmetric(                  horizontal: 7,                  vertical: 2,                ),                decoration: BoxDecoration(                  color: color.withValues(alpha: 0.20),                  borderRadius: BorderRadius.circular(20),                ),                child: Text(                  "$count",                  style: TextStyle(                    color: isEmpty ? Colors.white54 : color,                    fontSize: 12,                    fontWeight: FontWeight.bold,                  ),                ),              ),            ],          ),        ),      ),    );  }}